// 1. Represent 5 in Binary (8 bits)
let positiveFive = "00000101"; 

// 2. Step 1: Invert all bits (One's Complement)
// 0 -> 1, 1 -> 0
let inverted = "11111010";

// 3. Step 2: Add 1 to the inverted result
// 11111010 + 1 = 11111011
let negativeFive = "11111011";

